// This code has been fully generated by an AI.

package analysis

import "fmt"

// Record groups: efforts compete within a group. Indoor rides count for the
// power curve of "bike" but not for distances (virtual distance is not
// comparable with riding outside).
const (
	GroupBike = "bike"
	GroupRun  = "run"
	GroupHike = "hike"
)

// BikeDistances and RunDistances are the best-effort distances in meters.
var (
	BikeDistances = []int{5000, 10000, 20000, 40000, 100000}
	RunDistances  = []int{1000, 5000, 10000, 21097, 42195}
	// PowerDurations are the points of the power curve in seconds.
	PowerDurations = []int{5, 15, 30, 60, 120, 300, 600, 1200, 1800, 3600}
)

// EffortPlan says which efforts are computed for a sport category.
type EffortPlan struct {
	Group     string
	Distances []int
	Power     bool
	Climb     bool
	// SplitM is the length of automatic splits for activities without laps.
	SplitM float64
}

// PlanFor returns the effort plan of a sport category (see package sport).
func PlanFor(category string) EffortPlan {
	switch category {
	case "bike":
		return EffortPlan{Group: GroupBike, Distances: BikeDistances, Power: true, Climb: true, SplitM: 5000}
	case "indoor":
		return EffortPlan{Group: GroupBike, Power: true, SplitM: 5000}
	case "run":
		return EffortPlan{Group: GroupRun, Distances: RunDistances, Climb: true, SplitM: 1000}
	case "hike":
		return EffortPlan{Group: GroupHike, Climb: true, SplitM: 1000}
	}
	return EffortPlan{SplitM: 1000}
}

// DistanceLabel names a best-effort distance, e.g. "10 km" or "Halbmarathon".
func DistanceLabel(m int) string {
	switch m {
	case 21097:
		return "Halbmarathon"
	case 42195:
		return "Marathon"
	}
	if m%1000 == 0 {
		return fmt.Sprintf("%d km", m/1000)
	}
	return fmt.Sprintf("%d m", m)
}

// DurationLabel names a power-curve duration, e.g. "30 s", "5 min" or "1 h".
func DurationLabel(s int) string {
	switch {
	case s < 60:
		return fmt.Sprintf("%d s", s)
	case s%3600 == 0:
		return fmt.Sprintf("%d h", s/3600)
	case s%60 == 0:
		return fmt.Sprintf("%d min", s/60)
	}
	return fmt.Sprintf("%d s", s)
}
